for exp in ['e2','e3','e5','e6']:
 for dp,ds,fs in os.walk('experiments/'+exp):
  for fn in fs:
   if fn.endswith(('.txt','.md')):
    p=os.path.join(dp,fn)
    text=open(p,errors='ignore').read()
    if any(w in text.lower() for w in ['proper map','higher-dimensional','rational convex','rationally convex','higher dimensional']):
     print('\nFILE',p)
     lines=text.splitlines()
     for i,l in enumerate(lines):
      if any(w in l.lower() for w in ['proper map','higher-dimensional','rational convex','rationally convex','higher dimensional']): print('\n'.join(lines[max(0,i-1):i+3])[:1600])

